import assert from 'node:assert/strict';import {current,fixture,writeResults,repo}from'./fixtures.mjs';import{execFileSync}from'node:child_process';
const previous=await fixture(execFileSync('git',['show','c62ad3a:lie013-preview-7x9/worklet.js'],{cwd:repo,maxBuffer:32e6}).toString(),'v044-expansion');const tests=[],metrics=[];const run=(name,fn)=>{fn();tests.push(name);console.log('PASS',name);};
for(const sr of [44100,48000]){
 run(sr+': default glitch splice output matches V0.4.4, including long histories and HOLD',()=>{for(const tempo of [40,110]){const a=new current.PerformanceFX(sr),b=new previous.PerformanceFX(sr);for(let n=0;n<sr*3;n++){const tick=n*tempo*24/(60*sr),hold=n>sr*2.5;for(const f of[a,b])f.begin(tick,tempo,.85,'all',hold);for(let bus=0;bus<3;bus++){const x=.13*Math.sin(n*.013*(bus+1))+.04*Math.cos(n*.103),u=a.bus(bus,x,-x),v=b.bus(bus,x,-x);assert.equal(u[0],v[0]);assert.equal(u[1],v[1]);}a.end();b.end();}}});
 run(sr+': fragment control extends into phrases, stays bounded and preserves HOLD',()=>{const durations=[];for(const length of[0,.25,1]){const f=new current.PerformanceFX(sr);f.setLength(length);let max=0,changed=0,freeze=null;for(let n=0;n<sr*6;n++){const hold=n>=sr*5;f.begin(n*48/sr,120,.85,'all',hold);for(let i=0;i<3;i++){const x=.1*Math.sin(n*.032),y=f.bus(i,x,x);assert.ok(Number.isFinite(y[0]));if(Math.abs(y[0]-x)>1e-4)changed++;max=Math.max(max,f.buses[i].length);if(hold&&i===0){const now=[f.buses[0].anchor,f.buses[0].length];if(freeze)assert.deepEqual(now,freeze);freeze=now;}}f.end();}assert.ok(changed>sr);assert.ok(max<=sr*2);durations.push(max/sr);assert.equal(f.size,Math.ceil(sr*2.4));}assert.ok(durations[2]>.45&&durations[2]>durations[1]*8);assert.ok(durations[0]<durations[1]);metrics.push({sr,fragmentMaximumSeconds:durations});});
 run(sr+': long fragments cannot replay old silence after playback starts',()=>{const f=new current.PerformanceFX(sr);f.setLength(1);let peak=0,silentBlocks=0;for(let n=0;n<sr*8;n++){f.begin(n*48/sr,120,.85,'all',false);const x=n<sr*2?0:.12*Math.sin(n*.031);for(let bus=0;bus<3;bus++){const y=f.bus(bus,x,x)[0];if(bus===0)peak=Math.max(peak,Math.abs(y));}f.end();if(n%128===127){if(n>sr*2.02&&peak<1e-6)silentBlocks++;peak=0;}}assert.equal(silentBlocks,0);});
 run(sr+': global neutral output is exact and mode selection preserves every individual setting',()=>{const a=new current.Engine(sr),b=new current.Engine(sr);for(const e of[a,b]){e.configure({...current.defaultState(),rhythm:4});e.message({type:'drums',on:true});}b.configure({drumFxMode:'global'});const l=new Float32Array(128),r=new Float32Array(128),x=new Float32Array(128),y=new Float32Array(128);for(let n=0;n<sr;n+=128){a.process(l,r);b.process(x,y);assert.deepEqual(l,x);assert.deepEqual(r,y);}const settings=Array.from({length:7},(_,i)=>({pitch:i-3,spring:i/10,delay:(6-i)/10}));a.configure({drumFx:settings,drumSpringTone:-.6});const snapshot=JSON.stringify(a.drumFxSettings);a.configure({drumFxMode:'global',globalDrumFx:{pitch:8,spring:.7,delay:.4,tone:.8}});assert.ok(a.drumTuneTarget.every(x=>x===2**(8/12)));assert.equal(a.drumEffects.toneTarget,.8);assert.equal(JSON.stringify(a.drumFxSettings),snapshot);a.configure({drumFxMode:'individual'});assert.equal(a.drumEffects.toneTarget,-.6);for(let i=0;i<7;i++){assert.equal(a.drumTuneTarget[i],2**((i-3)/12));assert.equal(a.drumSendTargets[i*2],i/10);}assert.equal(a.globalDrumFx.pitch,8);assert.equal(a.globalDrumFx.spring,.7);});
 run(sr+': spring has a changed dispersive response, stereo spread and wet-only tone',()=>{
  const responses=[];for(const tone of[-1,0,1]){const e=new current.Engine(sr),fx=e.drumEffects;fx.setTone(tone);for(let n=0;n<sr*.3;n++)fx.process(1e-8,0);fx.reset();let energy=0,difference=0,peak=0,last=0,stereo=0,tail=0;const response=new Float32Array(Math.round(sr*.5));for(let n=0;n<sr*3;n++){const o=fx.process(n===0?1:0,0),v=o[0];energy+=v*v;difference+=(v-last)**2;last=v;peak=Math.max(peak,Math.abs(v));stereo+=(v-o[1])**2;if(n>sr)tail+=v*v;if(n<response.length)response[n]=v;assert.ok(Number.isFinite(v));}assert.ok(peak<.5&&energy>.001&&tail<energy*.05&&stereo>.001);responses.push({tone,energy,brightness:difference/energy,peak,tail,response});}
  assert.ok(responses[2].brightness>responses[0].brightness*2);const old=new previous.Engine(sr).drumEffects;let changed=0;for(let n=0;n<responses[1].response.length;n++)changed+=Math.abs(responses[1].response[n]-old.process(n===0?1:0,0)[0]);assert.ok(changed>1);
  const a=new current.Engine(sr),b=new current.Engine(sr);a.configure({drumSpringTone:-1});b.configure({drumSpringTone:1});a.drumEnv.fill(.8);b.drumEnv.fill(.8);a.drumPitch.fill(1);b.drumPitch.fill(1);for(let n=0;n<sr;n++)assert.equal(a.drumSample(),b.drumSample());metrics.push({sr,spring:responses.map(({response,...x})=>x),changedFromV044:changed});
 });
 run(sr+': switching active FX modes, tone and fragment extremes stays finite and clears on STOP',()=>{const e=new current.Engine(sr);e.message({type:'samples',zones:current.decodeSamples()});e.configure({...current.defaultState(),preset:'tape-strings',glitch:.85,globalDrumFx:{pitch:12,spring:1,delay:1,tone:1},drumFx:Array.from({length:7},()=>({pitch:-12,spring:1,delay:1}))});e.message({type:'sequence',on:true});const l=new Float32Array(128),r=new Float32Array(128);let peak=0;for(let n=0;n<sr*4;n+=128){if(n%4096===0)e.configure({drumFxMode:n%8192?'global':'individual',drumSpringTone:n%8192?1:-1,fragmentLength:n%8192?1:0});e.process(l,r);for(const v of l){assert.ok(Number.isFinite(v)&&Math.abs(v)<.881);peak=Math.max(peak,Math.abs(v));}}assert.ok(peak>.01);e.message({type:'stop'});for(let n=0;n<sr;n+=128)e.process(l,r);assert.equal(e.voices.length,0);assert.ok(l.every(x=>Math.abs(x)<1e-7));});
}writeResults('sound-expansion',tests,{metrics});
